export type Plan = "free" | "pro";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  plan: Plan;
  /** Set once the user has started (or completed) a Stripe Checkout session. */
  stripeCustomerId?: string;
};

const users: User[] = [
  {
    id: "1",
    email: "ada@example.com",
    name: "Ada",
    createdAt: "2026-01-04",
    plan: "free",
  },
  {
    id: "2",
    email: "grace@example.com",
    name: "Grace",
    createdAt: "2026-02-11",
    plan: "free",
  },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByStripeCustomerId(
  stripeCustomerId: string
): Promise<User | undefined> {
  return users.find((u) => u.stripeCustomerId === stripeCustomerId);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  return users[0];
}

/** Remembers which Stripe customer a user maps to, so future webhook events can find them. */
export async function setUserStripeCustomerId(
  id: string,
  stripeCustomerId: string
): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  if (!user) return undefined;
  user.stripeCustomerId = stripeCustomerId;
  return user;
}

export async function setUserPlan(
  id: string,
  plan: Plan
): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  if (!user) return undefined;
  user.plan = plan;
  return user;
}

/** Called by the Stripe webhook once a subscription payment succeeds. */
export async function upgradeUserToPro(id: string): Promise<User | undefined> {
  return setUserPlan(id, "pro");
}

/** Called by the Stripe webhook when a subscription is cancelled or payment fails for good. */
export async function downgradeUserToFree(
  id: string
): Promise<User | undefined> {
  return setUserPlan(id, "free");
}

