import { NextRequest, NextResponse } from "next/server";
import type Stripe from "stripe";
import { getStripe } from "@/lib/stripe";
import {
  downgradeUserToFree,
  getUserByStripeCustomerId,
  setUserStripeCustomerId,
  upgradeUserToPro,
} from "@/lib/users";

// Needs the raw request body to verify the Stripe signature, and Stripe's
// SDK relies on Node APIs — keep this off the edge runtime.
export const runtime = "nodejs";

export async function POST(req: NextRequest) {
  const signature = req.headers.get("stripe-signature");
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

  if (!webhookSecret) {
    console.error("STRIPE_WEBHOOK_SECRET is not set; rejecting webhook.");
    return NextResponse.json(
      { error: "Webhook is not configured." },
      { status: 500 }
    );
  }
  if (!signature) {
    return NextResponse.json(
      { error: "Missing stripe-signature header." },
      { status: 400 }
    );
  }

  const stripe = getStripe();
  const rawBody = await req.text();

  let event: Stripe.Event;
  try {
    event = stripe.webhooks.constructEvent(rawBody, signature, webhookSecret);
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error";
    console.error(`Stripe webhook signature verification failed: ${message}`);
    return NextResponse.json({ error: "Invalid signature." }, { status: 400 });
  }

  switch (event.type) {
    // Fires once the customer has successfully paid for their first period.
    case "checkout.session.completed": {
      const session = event.data.object as Stripe.Checkout.Session;
      const userId = session.client_reference_id ?? session.metadata?.userId;

      if (!userId) {
        console.error("checkout.session.completed had no userId reference.");
        break;
      }
      if (typeof session.customer === "string") {
        await setUserStripeCustomerId(userId, session.customer);
      }
      if (session.mode === "subscription" && session.payment_status === "paid") {
        await upgradeUserToPro(userId);
      }
      break;
    }

    // Covers renewals/recoveries after a past_due period, and downgrades a
    // subscription that Stripe has given up on retrying.
    case "customer.subscription.updated":
    case "customer.subscription.deleted": {
      const subscription = event.data.object as Stripe.Subscription;
      const customerId =
        typeof subscription.customer === "string"
          ? subscription.customer
          : subscription.customer.id;

      const user = await getUserByStripeCustomerId(customerId);
      if (!user) break;

      const isActive =
        subscription.status === "active" || subscription.status === "trialing";
      if (isActive) {
        await upgradeUserToPro(user.id);
      } else if (
        subscription.status === "canceled" ||
        subscription.status === "unpaid"
      ) {
        await downgradeUserToFree(user.id);
      }
      break;
    }

    default:
      break;
  }

  return NextResponse.json({ received: true });
}

