import { getCurrentUser, listUsers } from "@/lib/users";
import { startProCheckout } from "./actions";

export default async function DashboardPage({
  searchParams,
}: {
  searchParams: Promise<{ checkout?: string }>;
}) {
  const me = await getCurrentUser();
  const all = await listUsers();
  const { checkout } = await searchParams;

  return (
    <main className="mx-auto max-w-2xl p-8">
      <h1 className="text-2xl font-semibold">Dashboard</h1>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.name ?? "nobody"} ({me?.email ?? "—"})
      </p>

      {checkout === "success" && (
        <p className="mt-4 rounded-md bg-green-100 px-3 py-2 text-sm text-green-800 dark:bg-green-900/40 dark:text-green-200">
          Payment received — your plan updates as soon as Stripe confirms it
          via webhook (this is usually instant).
        </p>
      )}
      {checkout === "cancelled" && (
        <p className="mt-4 rounded-md bg-amber-100 px-3 py-2 text-sm text-amber-800 dark:bg-amber-900/40 dark:text-amber-200">
          Checkout was cancelled — you have not been charged.
        </p>
      )}

      <section className="mt-8 rounded-lg border border-black/10 p-4 dark:border-white/10">
        <div className="flex items-center justify-between gap-4">
          <div>
            <h2 className="text-lg font-medium">Plan</h2>
            <p className="mt-1 text-sm opacity-70">
              Current plan:{" "}
              <span className="font-medium uppercase">{me?.plan ?? "free"}</span>
            </p>
          </div>

          {me && me.plan !== "pro" && (
            <form action={startProCheckout}>
              <button
                type="submit"
                className="whitespace-nowrap rounded-full bg-foreground px-4 py-2 text-sm font-medium text-background transition-colors hover:bg-[#383838] dark:hover:bg-[#ccc]"
              >
                Upgrade to Pro — $12/mo
              </button>
            </form>
          )}
        </div>
      </section>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt} —{" "}
            <span className="uppercase opacity-70">{u.plan}</span>
          </li>
        ))}
      </ul>
    </main>
  );
}

